public class SysUtils {
  public static void installToolbar(final Project project, final JPanel panel) {
    if (project == null || panel == null) {
      throw new IllegalArgumentException("Langvis toolbar requires a project and panel");
    }
    ToolWindowManager.getInstance(project).invokeLater(() -> {
      {
        if (project.isDisposed() || panel.getClientProperty("langvis.toolbar") != null) {
          return;
        }
        ActionGroup group = ActionUtils.getGroup("com.dslfoundry.langvis.plugin.plugin.Toolbar_ActionGroup");
        ActionToolbar toolbar = ActionManager.getInstance().createActionToolbar(ActionPlaces.TOOLBAR, group, true);
        toolbar.setTargetComponent(panel);
        panel.add(toolbar.getComponent(), BorderLayout.PAGE_START);
        panel.putClientProperty("langvis.toolbar", toolbar);
        panel.revalidate();
      }
    });
  }
  public static void renderPlantUMLToSvg(String pumlFilePath, String svgFilePath) throws IOException {
    String source = Files.readString(Paths.get(pumlFilePath), StandardCharsets.UTF_8);
    SourceStringReader reader = new SourceStringReader(source);
    Path outputPath = Paths.get(svgFilePath).toAbsolutePath();
    Files.createDirectories(outputPath.getParent());
    Path temporaryFile = Files.createTempFile(outputPath.getParent(), "langvis-", ".svg");
    try {
      try (OutputStream output = Files.newOutputStream(temporaryFile)) {
        DiagramDescription description = reader.outputImage(output, new FileFormatOption(FileFormat.SVG));
        if (description == null || description.getDescription().contains("Error")) {
          throw new IOException("PlantUML could not render the diagram: " + description);
        }
      }
      if (Files.size(temporaryFile) == 0) {
        throw new IOException("PlantUML produced an empty SVG file");
      }
      Files.move(temporaryFile, outputPath, StandardCopyOption.REPLACE_EXISTING);
    } finally {
      Files.deleteIfExists(temporaryFile);
    }
  }
  public static void reportError(final Project project, final String message) {
    ApplicationManager.getApplication().invokeLater(() -> {
      if (!(project.isDisposed())) {
        MessagesViewTool.getInstance(ProjectHelper.fromIdeaProject(project)).add(new Message(MessageKind.ERROR, "Language Visualization", message));
      }
    });
  }
  public static boolean isStructureModel(SModel model) {
    return model != null && LanguageAspect.STRUCTURE.is(model);
  }
}
